<?php
namespace Tests\Feature;
use App\Contracts\FaceProvider;use App\Jobs\{IndexFaceAsset,PruneBiometricData,SearchFaces,WithdrawBiometricConsent};use App\Models\{BiometricConsent,FaceMatchResult,FaceSearchSubject,Group,MediaAsset,MediaVariant,Photo,User};use App\Services\Face\{FaceRecognitionManager,FakeFaceProvider};use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Http\UploadedFile;use Illuminate\Support\Facades\{Hash,Queue,Storage};use Illuminate\Support\Str;use Tests\TestCase;
class DurableFaceRecognitionTest extends TestCase{use RefreshDatabase;protected function setUp():void{parent::setUp();config(['face.provider'=>'fake','face.threshold'=>95,'face.manual_review'=>true,'media.disk'=>'private_local','queue.default'=>'sync']);Storage::fake('private_local');FakeFaceProvider::reset();}private function user(string$e):User{return User::create(['name'=>'Person','email'=>$e,'password'=>Hash::make('x'),'status'=>'active','account_type'=>'photographer','plan'=>'basic']);}private function group(User$u):Group{$g=Group::create(['name'=>'Event','creator_id'=>$u->id,'face_recognition_enabled'=>true]);$g->members()->attach($u->id,['role'=>'admin','membership_status'=>'active','access_type'=>'full_access']);return$g;}private function asset(Group$g,User$u):MediaAsset{$key='media/originals/groups/'.$g->id.'/'.Str::uuid().'.jpg';Storage::disk('private_local')->put($key,'face-bytes');$p=Photo::create(['group_id'=>$g->id,'uploader_id'=>$u->id,'filename'=>'safe.jpg','original_filename'=>'safe.jpg','path'=>$key,'thumbnail_path'=>$key,'file_size'=>10,'mime_type'=>'image/jpeg']);$a=MediaAsset::create(['uuid'=>(string)Str::uuid(),'photo_id'=>$p->id,'group_id'=>$g->id,'owner_id'=>$u->id,'uploader_id'=>$u->id,'storage_disk'=>'private_local','original_object_key'=>$key,'original_filename'=>'safe.jpg','mime_type'=>'image/jpeg','size_bytes'=>10,'checksum_sha256'=>hash('sha256','face-bytes'),'state'=>'completed']);MediaVariant::create(['media_asset_id'=>$a->id,'variant_type'=>'original','storage_disk'=>'private_local','object_key'=>$key,'mime_type'=>'image/jpeg','size_bytes'=>10,'checksum_sha256'=>hash('sha256','face-bytes'),'state'=>'ready']);return$a;}
 public function test_provider_is_configurable_and_identifiers_remain_internal():void{$this->assertInstanceOf(FakeFaceProvider::class,app(FaceProvider::class));$u=$this->user('a@test.local');$g=$this->group($u);$a=$this->asset($g,$u);(new IndexFaceAsset($a->id))->handle(app(FaceRecognitionManager::class));$this->assertDatabaseCount('indexed_faces',1);$this->assertDatabaseHas('face_collections',['group_id'=>$g->id,'provider'=>'fake']);}
 public function test_consent_is_required_and_selfie_is_private():void{Queue::fake();$u=$this->user('b@test.local');$g=$this->group($u);$this->actingAs($u)->postJson(route('biometric.search',$g),['consent_uuid'=>(string)Str::uuid(),'selfie'=>UploadedFile::fake()->image('selfie.jpg')])->assertNotFound();$consent=$this->postJson(route('biometric.consent',$g),['accepted'=>true,'privacy_notice_version'=>'2026-08'])->assertCreated()->json('consent_uuid');$this->postJson(route('biometric.search',$g),['consent_uuid'=>$consent,'selfie'=>UploadedFile::fake()->image('selfie.jpg')])->assertAccepted()->assertJson(['state'=>'queued']);$subject=FaceSearchSubject::firstOrFail();Storage::disk('private_local')->assertExists($subject->object_key);Storage::disk('public')->assertMissing($subject->object_key);Queue::assertPushed(SearchFaces::class);}
 public function test_fake_search_persists_thresholded_durable_results():void{$u=$this->user('c@test.local');$g=$this->group($u);$a=$this->asset($g,$u);config(['face.fake_matches'=>[['external_id'=>$a->uuid,'face_id'=>'provider-internal','similarity'=>97.5],['external_id'=>'unknown','face_id'=>'x','similarity'=>99.0]]]);$c=BiometricConsent::create(['uuid'=>(string)Str::uuid(),'group_id'=>$g->id,'user_id'=>$u->id,'privacy_notice_version'=>'v1','state'=>'granted','granted_at'=>now()]);$key='media/temp/selfies/groups/'.$g->id.'/'.Str::uuid().'.jpg';Storage::disk('private_local')->put($key,'selfie');$s=FaceSearchSubject::create(['uuid'=>(string)Str::uuid(),'biometric_consent_id'=>$c->id,'group_id'=>$g->id,'user_id'=>$u->id,'storage_disk'=>'private_local','object_key'=>$key,'checksum_sha256'=>hash('sha256','selfie'),'state'=>'queued','expires_at'=>now()->addDay()]);(new SearchFaces($s->id))->handle(app(FaceRecognitionManager::class));$this->assertDatabaseHas('face_match_results',['face_search_subject_id'=>$s->id,'media_asset_id'=>$a->id,'review_state'=>'unreviewed']);$response=$this->actingAs($u)->getJson(route('biometric.show',$s))->assertOk();$response->assertJsonMissing(['provider-internal']);}
 public function test_cross_event_and_cross_user_access_are_denied():void{$u=$this->user('d@test.local');$g=$this->group($u);$other=$this->user('e@test.local');$this->group($other);$c=BiometricConsent::create(['uuid'=>(string)Str::uuid(),'group_id'=>$g->id,'user_id'=>$u->id,'privacy_notice_version'=>'v1','state'=>'granted','granted_at'=>now()]);$s=FaceSearchSubject::create(['uuid'=>(string)Str::uuid(),'biometric_consent_id'=>$c->id,'group_id'=>$g->id,'user_id'=>$u->id,'storage_disk'=>'private_local','object_key'=>'media/temp/selfies/x.jpg','checksum_sha256'=>str_repeat('a',64),'state'=>'queued','expires_at'=>now()->addDay()]);$this->actingAs($other)->getJson(route('biometric.show',$s))->assertForbidden();$this->deleteJson(route('biometric.withdraw',$c))->assertForbidden();}
 public function test_withdrawal_and_retention_delete_private_selfie_and_results():void{$u=$this->user('f@test.local');$g=$this->group($u);$a=$this->asset($g,$u);$c=BiometricConsent::create(['uuid'=>(string)Str::uuid(),'group_id'=>$g->id,'user_id'=>$u->id,'privacy_notice_version'=>'v1','state'=>'granted','granted_at'=>now()]);$key='media/temp/selfies/expired.jpg';Storage::disk('private_local')->put($key,'selfie');$s=FaceSearchSubject::create(['uuid'=>(string)Str::uuid(),'biometric_consent_id'=>$c->id,'group_id'=>$g->id,'user_id'=>$u->id,'storage_disk'=>'private_local','object_key'=>$key,'checksum_sha256'=>hash('sha256','selfie'),'state'=>'completed','expires_at'=>now()->subMinute()]);FaceMatchResult::create(['face_search_subject_id'=>$s->id,'media_asset_id'=>$a->id,'similarity'=>98,'expires_at'=>now()->subMinute()]);(new PruneBiometricData)->handle(app(FaceRecognitionManager::class));Storage::disk('private_local')->assertMissing($key);$this->assertDatabaseMissing('face_search_subjects',['id'=>$s->id]);$c2=BiometricConsent::create(['uuid'=>(string)Str::uuid(),'group_id'=>$g->id,'user_id'=>$u->id,'privacy_notice_version'=>'v1','state'=>'granted','granted_at'=>now()]);$k2='media/temp/selfies/withdraw.jpg';Storage::disk('private_local')->put($k2,'selfie');FaceSearchSubject::create(['uuid'=>(string)Str::uuid(),'biometric_consent_id'=>$c2->id,'group_id'=>$g->id,'user_id'=>$u->id,'storage_disk'=>'private_local','object_key'=>$k2,'checksum_sha256'=>hash('sha256','selfie'),'state'=>'completed','expires_at'=>now()->addDay()]);$this->actingAs($u)->deleteJson(route('biometric.withdraw',$c2))->assertOk();Storage::disk('private_local')->assertMissing($k2);$this->assertSame('withdrawn',$c2->fresh()->state);}
 public function test_provider_health_returns_sanitized_status():void{$this->assertSame(['healthy'=>true,'provider'=>'fake'],app(FaceProvider::class)->health());}
}
